import java.util.Scanner;

class Animal {
    String name;

    Animal(String name) {
        this.name = name;
    }

    void speak() {
        System.out.println(name + "：……");
    }
}

class Cat extends Animal {
    Cat(String name) {
        super(name);
    }

    @Override
    void speak() {
        System.out.println(name + "：喵～");
    }
}

class Dog extends Animal {
    Dog(String name) {
        super(name);
    }

    @Override
    void speak() {
        System.out.println(name + "：汪！");
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Animal[] pets = new Animal[n + 1];
        for (int i = 0; i < n; i++) {
            pets[i] = new Cat("小橘");
        }
        pets[n] = new Dog("大黄");
        for (Animal pet : pets) {
            pet.speak();
        }
        int cats = 0;
        for (Animal pet : pets) {
            if (pet instanceof Cat) {
                cats++;
            }
        }
        System.out.println("这一排里有 " + cats + " 只猫");
    }
}

